using System;
using System.Reflection;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonCatAcquisitionVerification
    {
        static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
        public static void Regression(){PythonEventLayout.BuildAndVerify();PythonRecruitmentSetup.BuildAndVerify();PythonRegularIntroductionSetup.BuildAndVerify();PythonDispatchIntroductionSetup.BuildAndVerify();PythonVisitingCatSetup.BuildAndVerify();Debug.Log("CAT_CAFE_ACQUISITION_REGRESSION_OK");}
        public static void BuildAndVerify()
        {
            PythonCatAcquisitionLayout.Build();var p=UnityEngine.Object.FindObjectOfType<ContentPreview>();p.Initialize();var c=p.GetComponent<PythonStateClient>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",flags).SetValue(c,p);
            var state=PythonServiceSetup.Sample();state.instance_id="acquisition-test";state.can_set_shifts=true;state.closed=false;state.required_action="";state.funds=1000;
            state.housing=new PythonHousingState{configured=true,count=5,capacity=6,free=1,can_expand=true,next_capacity=8,cost=300,funds_after=700,kind="expand_housing"};
            state.recruitment=new PythonRecruitment{housing="在籍5匹 / 上限6匹 / 空き1匹",rows=new[]{new PythonRecruitmentCat{cat_id=state.cats[0].cat_id,name="保護猫候補",content_cat_id=state.cats[0].content_cat_id,cost=200,funds_after=800,can_purchase=true,features=new[]{"白猫"},trait_id="friendly",details="名前 / 個性：保護猫候補 / 穏やかな甘えん坊\n特徴：白猫 / 短毛\n特性：接客上手\n"+new string('あ',1400)},new PythonRecruitmentCat{cat_id="other",name="別の候補",features=new[]{"黒猫"}}},traits=new[]{new PythonRecruitmentOption{id="friendly",label="接客上手"}},coats=new[]{new PythonRecruitmentOption{id="白猫",label="白猫"}},hairs=new PythonRecruitmentOption[0]};
            state.pet_shop=new PythonPetShop{housing=state.recruitment.housing,rows=new[]{new PythonShopCat{cat_id=state.cats[1].cat_id,name="ショップ候補",content_cat_id=state.cats[1].content_cat_id,cost=400,funds_after=600,can_purchase=true,details="名前 / 個性：ショップ候補 / 好奇心旺盛\n特徴：キジトラ / 短毛\n特性：遊び好き"}}};
            state.regular_introduction=new PythonRegularIntroduction{cat_id=state.cats[0].cat_id,name="常連の紹介猫",status="waiting",cost=200,funds_after=800,can_accept=true,can_decline=true,personality="穏やか",features="白猫 / 短毛",housing=state.recruitment.housing};
            state.dispatch_introductions=new[]{new PythonDispatchIntroduction{event_id="intro-1",cat_id=state.cats[1].cat_id,name="派遣先の紹介猫",status="waiting",cost=300,funds_after=700,can_accept=true,can_decline=true,housing=state.recruitment.housing,destination="近所のお店",sender_name="店主",personality="好奇心旺盛",features="キジトラ / 短毛"}};
            state.visiting_cat=new PythonVisitingCat{cat_id=state.cats[0].cat_id,name="店先の猫",status="ready",cost=200,funds_after=800,can_accept=true,can_skip=true,required=3,progress=3,housing=state.recruitment.housing,personality="穏やか",features="白猫 / 短毛"};
            state.intake_request=new PythonIntakeState{cat_id=state.cats[1].cat_id,name="依頼の猫",status="waiting",cost=200,can_accept=true,can_decline=true,housing=state.recruitment.housing,personality="好奇心旺盛",features="キジトラ / 短毛"};
            var nav=p.GetComponent<PythonCatAcquisitionNavigation>();Action apply=()=>{typeof(PythonStateClient).GetMethod("Accept",flags).Invoke(c,new object[]{state});nav.Refresh();};Action clear=()=>typeof(PythonStateClient).GetField("pending",flags).SetValue(c,null);Func<PythonShiftCommand> pending=()=>typeof(PythonStateClient).GetField("pending",flags).GetValue(c) as PythonShiftCommand;apply();p.GetComponent<PythonPreparationPanel>().Close();
            var r=p.GetComponent<PythonRecruitmentPanel>();var shop=p.GetComponent<PythonPetShopPanel>();var regular=p.GetComponent<PythonRegularIntroductionPanel>();var dispatch=p.GetComponent<PythonDispatchIntroductionPanel>();var visiting=p.GetComponent<PythonVisitingCatPanel>();var intake=p.GetComponent<PythonIntakePanel>();var h=p.GetComponent<PythonHousingPanel>();var menu=p.GetComponent<PythonMenuPanel>();
            menu.Open();menu.SelectGroup(1);menu.Select(16);r.coat.value=1;r.trait.value=1;Canvas.ForceUpdateCanvases();var scroll=r.details.GetComponentInParent<ScrollRect>();scroll.verticalNormalizedPosition=.35f;string selected=r.Row.cat_id;r.Housing();Check(h.panel.activeSelf && h.close.GetComponentInChildren<Text>().text=="猫の候補へ戻る","Housing entry failed");state.revision++;state.housing.capacity=8;state.housing.free=3;apply();h.close.onClick.Invoke();Check(r.panel.activeSelf && r.Row.cat_id==selected && r.coat.value==1 && r.trait.value==1 && Math.Abs(scroll.verticalNormalizedPosition-.35f)<.01f,"Housing return lost candidate/filter/scroll");Check(r.close.GetComponentInChildren<Text>().text=="メニューへ戻る","Housing lost menu context");Check(nav.summaries[0].text.Contains("空き 3匹"),"Updated housing absent");Capture(p,"AcquisitionRecruitment");r.close.onClick.Invoke();Check(menu.panel.activeSelf && menu.SelectedGroup==1,"Menu return category lost");menu.Close();
            Action[] opens={r.Open,shop.Open,regular.Open,dispatch.Open,visiting.Open,()=>{intake.panel.SetActive(true);intake.panel.transform.SetAsLastSibling();}};Action[] housing={r.Housing,shop.Housing,regular.Housing,dispatch.Housing,visiting.Housing,intake.Housing};
            for(int i=0;i<6;i++){foreach(var panel in nav.panels)panel.SetActive(false);opens[i]();housing[i]();Check(h.panel.activeSelf,"Housing unavailable at "+i);state.revision++;apply();h.close.onClick.Invoke();Check(nav.panels[i].activeSelf,"Candidate return failed at "+i);Check(pending()==null,"Browsing sent command at "+i);nav.Refresh();Capture(p,"Acquisition"+i);}
            Action[] choose={shop.Purchase,regular.Accept,dispatch.Accept,visiting.Accept};Action[] confirm={shop.Confirm,regular.Confirm,dispatch.Confirm,visiting.Confirm};string[] kinds={"purchase_cat","resolve_regular_introduction","resolve_dispatch_introduction","resolve_visiting_cat"};
            for(int i=0;i<4;i++){choose[i]();Check(pending()==null,"Choice sent before confirmation "+i);confirm[i]();Check(pending()!=null && pending().kind==kinds[i],"Candidate command wrong "+i);if(i==2)Check(pending().event_id=="intro-1","Dispatch introduction event ID lost");clear();state.revision++;apply();}
            intake.Accept();Check(intake.confirmation.activeSelf && pending()==null && intake.confirmationText.text.Contains("800"),"Intake confirmation sent early");Capture(p,"AcquisitionIntakeConfirmation");intake.Cancel();Check(!intake.confirmation.activeSelf && pending()==null,"Intake cancel sent command");intake.Decline();state.revision++;apply();Check(!intake.confirmation.activeSelf,"Stale intake confirmation retained");intake.Accept();intake.Disconnect();Check(!intake.confirmation.activeSelf && !intake.confirm.interactable,"Offline intake confirmation enabled");apply();
            intake.Accept();intake.Confirm();Check(pending()?.kind=="resolve_intake" && pending().choice=="accept","Intake command incorrect");string request=pending().request_id;intake.Confirm();Check(pending().request_id==request,"Duplicate intake command");nav.Refresh();Check(!nav.joinedEntry.gameObject.activeSelf,"Unacknowledged admission shown");clear();state.intake_request.status="accepted";state.revision++;apply();Check(nav.joinedEntry.gameObject.activeSelf,"Intake joined entry missing");nav.joinedEntry.onClick.Invoke();Check(p.GetComponent<PythonCatDetailsPanel>().panel.activeSelf,"Joined cat details absent");p.GetComponent<PythonCatDetailsPanel>().Close();
            foreach(var panel in nav.panels)panel.SetActive(false);r.Open();r.Purchase();r.Confirm();Check(pending()?.kind=="recruit_cat" && pending().cat_id==selected,"Recruitment command incorrect");clear();state.recruitment.rows[0].accepted=true;state.recruitment.rows[0].can_purchase=false;state.revision++;apply();Check(r.Row==null && nav.joinedEntry.gameObject.activeSelf,"Hidden accepted recruitment lost joined entry");r.accepted.isOn=true;nav.Refresh();Check(nav.detailEntries[0].gameObject.activeSelf && nav.detailEntries[0].interactable,"Accepted recruitment detail missing");nav.detailEntries[0].onClick.Invoke();Check(!r.panel.activeSelf && p.GetComponent<PythonCatDetailsPanel>().panel.activeSelf,"Candidate detail navigation failed");p.GetComponent<PythonCatDetailsPanel>().Close();
            state.pet_shop.rows[0].accepted=true;state.pet_shop.rows[0].can_purchase=false;state.regular_introduction.status="accepted";state.dispatch_introductions[0].status="accepted";state.visiting_cat.status="accepted";state.revision++;apply();for(int i=0;i<5;i++)Check(nav.detailEntries[i].interactable,"Accepted detail disabled at "+i);
            typeof(PythonStateClient).GetField("online",flags).SetValue(c,false);nav.Refresh();Check(!nav.joinedEntry.interactable && !nav.detailEntries[0].interactable,"Disconnected joined details enabled");typeof(PythonStateClient).GetField("online",flags).SetValue(c,true);state.instance_id="loaded-instance";apply();Check(!nav.joinedEntry.gameObject.activeSelf,"Load retained joined entry");Check(pending()==null,"UI browsing queued command");Debug.Log("CAT_CAFE_ACQUISITION_NAVIGATION_OK: six screens / housing return / filters / scroll / menu / confirmations / cancel / offline / stable IDs / acknowledged joins / details / reset");
        }
        static void Capture(ContentPreview p,string name){Canvas.ForceUpdateCanvases();var records=p.GetComponent<PythonDispatchIntroductionPanel>().records;if(records.gameObject.activeInHierarchy)Check(!string.IsNullOrEmpty(records.captionText.text) && records.captionText.preferredHeight<=records.captionText.rectTransform.rect.height+1,"Introduction selector caption clipped");var nav=p.GetComponent<PythonCatAcquisitionNavigation>();foreach(var t in nav.summaries)if(t.gameObject.activeInHierarchy)Check(t.preferredHeight<=t.rectTransform.rect.height+1,"Candidate summary clipped");typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{p,"Logs/"+name+".png"});}
    }
}
